//! 🎟️ Original binary command decoding pays bounded reads and retains every partial field until delivery or close.
use super::*;
use std::mem::size_of;
use semio_framework_job::{StepContext,OriginalTurnFailure};
use semio_framework_value::{RetainedCloneGrant as Grant,RetainedCloneProgress as Progress,RetainedCloneStep as Step,RetainedWorkOutcome as Turn,RetirementDemand as Demand,ValueError,ValueRefusalKind,retained_clone_grant_admits,retirement::{RetireOwned,controlled::ControlledRetirement}};
use ::protocol::wire::command_ingress::{OriginalCommandField,OriginalCommandVarint};
#[derive(Debug,Default,semio_framework_value::RetireOwned)]
#[value(crate="::semio_framework_value")]
pub(super) struct OriginalCommandDecode{tag:Option<u8>,seq:Option<u64>,index:usize,varint:OriginalCommandVarint,field:OriginalCommandField,bytes:[Option<Vec<u8>>;3],texts:[Option<String>;10],numbers:[Option<u64>;5],selection:Option<u8>,ops:Vec<Vec<u8>>,op:Option<Vec<u8>>,ops_reserved:bool,archive:DocumentArchivePack,archive_stage:u8,archive_reserved:bool,query:Option<::protocol::LocalInteractionQueryCommand>,prepared:Option<AppCommand>}
pub(super) type OriginalCursorClose=ControlledRetirement<(PagedCommandReader,PagedAppCommandDecodeState,OriginalCommandDecode)>;
#[derive(Clone,Copy)]
enum Atom{Bytes(usize),Text(usize),Number(usize),Selection,Ops,Archive,Finish}
fn invalid(message:&'static str)->OriginalTurnFailure{ValueError::literal(ValueRefusalKind::InvalidValue,message).into()}
fn pay(cx:&mut StepContext<'_>,bytes:usize,work:u64)->Result<bool,OriginalTurnFailure>{if cx.fuel_remaining()<work||!retained_clone_grant_admits(cx.retained_grant(),Demand{copy_bytes:bytes,depth:1,..Default::default()}){return Ok(false)}cx.consume_retained(Progress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(work);Ok(true)}
fn debit(turn:Turn<Step>,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{cx.consume_fuel(turn.work);match turn.result{Ok(step)=>cx.consume_retained(step.progress()).map_err(Into::into),Err(error)=>Err(OriginalTurnFailure::debit_original(error,cx))}}
fn reserve<T>(out:&mut Vec<T>,count:usize,ready:&mut bool,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if *ready{return Ok(true)}if !out.is_empty()||out.capacity()!=0{return Err(invalid("command roster reserve requires an empty original home"))}let capacity=count.checked_mul(size_of::<T>()).ok_or_else(||invalid("command roster extent overflow"))?;let bytes=size_of::<Vec<T>>()+size_of::<bool>();let grant=cx.retained_grant();if cx.fuel_remaining()<1||!retained_clone_grant_admits(grant,Demand{copy_bytes:bytes,capacity_bytes:capacity,depth:1,..Default::default()}){return Ok(false)}cx.consume_fuel(1);if out.try_reserve_exact(count).is_err(){return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"command roster backing allocation refused").into())}let progress=Progress{copied_items:1,copied_bytes:bytes,retained_capacity_bytes:out.capacity()*size_of::<T>(),..Default::default()};*ready=true;if !progress.fits(grant){return Err(OriginalTurnFailure::debit_original(ValueError::literal(ValueRefusalKind::InvariantViolated,"command roster allocation exceeded its funded quote").with_retained_progress(progress),cx))}cx.consume_retained(progress)?;Ok(false)}
impl OriginalCommandDecode{
 fn plan(&self)->Result<Atom,OriginalTurnFailure>{use Atom::*;let i=self.index;Ok(match self.tag.unwrap(){
  0|3|4=>if i==0{Bytes(0)}else{Finish},1|8|13=>match i{0=>Bytes(0),1=>Bytes(1),_=>Finish},2=>if i==0{Text(0)}else{Finish},
  7|9|15|16|27|31|33|41|42=>Finish,10=>match i{0=>Text(0),1=>Bytes(0),2=>Bytes(1),_=>Finish},11=>match i{0=>Text(0),1=>Bytes(0),_=>Finish},12|18..=21=>if i==0{Text(0)}else{Finish},
  17=>match i{0=>Text(0),1=>Text(1),2=>Bytes(0),3=>Ops,4=>Bytes(1),5=>Bytes(2),_=>Finish},29=>if i==0{Bytes(0)}else{Finish},30=>match i{0=>Text(0),1=>Text(1),2=>Bytes(0),_=>Finish},
  32|43=>if i==0{Archive}else{Finish},34..=36=>if i==0{Number(0)}else{Finish},37=>match i{0=>Text(0),1=>Text(1),2=>Number(0),3=>Selection,4 if self.selection==Some(1)=>Text(2),_=>Finish},38..=40=>match i{0=>Number(0),1=>Text(0),2=>Number(1),3=>Number(2),4=>Number(3),_=>Finish},
  _=>return Err(invalid("command kind requires a distinct route-specific ingress"))
 })}
 fn number(&mut self,index:usize,reader:&mut PagedCommandReader,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.numbers[index].is_some(){return Ok(true)}let grant=cx.retained_grant();let work=cx.fuel_remaining();let turn=if self.varint.value().is_some(){self.varint.transfer_source_step(&mut self.numbers[index],grant,work)}else{self.varint.step(reader,grant,work)};debit(turn,cx)?;Ok(false)}
 fn field(&mut self,index:usize,text:bool,maximum:usize,reader:&mut PagedCommandReader,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if if text{self.texts[index].is_some()}else{self.bytes[index].is_some()}{return Ok(true)}let grant=cx.retained_grant();let work=cx.fuel_remaining();let turn=if self.field.bytes().is_some(){if text&&self.tag==Some(37)&&index==2&&(self.field.bytes().unwrap().is_empty()||self.field.characters().unwrap()>512){return Err(invalid("checkpoint identity exceeds its exact text authority"))}if text{self.field.transfer_text_source_step(&mut self.texts[index],grant,work)}else{self.field.transfer_bytes_source_step(&mut self.bytes[index],grant,work)}}else{self.field.step(reader,maximum,text,grant,work)};debit(turn,cx)?;Ok(false)}
 fn advance(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{if pay(cx,size_of::<usize>(),1)?{self.index+=1}Ok(())}
 fn ops(&mut self,reader:&mut PagedCommandReader,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.number(4,reader,cx)?{return Ok(false)}let count=usize::try_from(self.numbers[4].unwrap()).map_err(|_|invalid("prepared op count is not representable"))?;if count>TRANSACTION_PREPARED_OPS_MAXIMUM{return Err(invalid("prepared op count exceeds its exact roster authority"))}if !reserve(&mut self.ops,count,&mut self.ops_reserved,cx)?{return Ok(false)}if self.ops.len()==count{return Ok(true)}if self.op.is_none(){let grant=cx.retained_grant();let work=cx.fuel_remaining();let turn=if self.field.bytes().is_some(){self.field.transfer_bytes_source_step(&mut self.op,grant,work)}else{self.field.step(reader,APP_COMMAND_FIELD_MAXIMUM_BYTES,false,grant,work)};debit(turn,cx)?;return Ok(false)}let bytes=size_of::<Vec<Vec<u8>>>()+size_of::<Option<Vec<u8>>>()+size_of::<Vec<u8>>();if pay(cx,bytes,1)?{self.ops.push(self.op.take().unwrap())}Ok(false)}
 fn archive(&mut self,reader:&mut PagedCommandReader,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  let stage=self.archive_stage;
  if stage<=1{let index=stage as usize;if !self.field(index,false,APP_COMMAND_FIELD_MAXIMUM_BYTES,reader,cx)?{return Ok(false)}if pay(cx,size_of::<Option<Vec<u8>>>()+size_of::<Vec<u8>>()+size_of::<u8>(),1)?{let field=self.bytes[index].take().unwrap();if stage==0{self.archive.parent_pack=field}else{self.archive.parent_spr=field}self.archive_stage+=1}return Ok(false)}
  if stage==2{if !self.number(4,reader,cx)?{return Ok(false)}let count=usize::try_from(self.numbers[4].unwrap()).map_err(|_|invalid("archive member count is not representable"))?;if count>DOCUMENT_ARCHIVE_MAXIMUM_MEMBERS{return Err(invalid("archive member count exceeds its exact roster authority"))}if !reserve(&mut self.archive.members,count,&mut self.archive_reserved,cx)?{return Ok(false)}if pay(cx,size_of::<u8>(),1)?{self.archive_stage=if count==0{16}else{3}}return Ok(false)}
  if stage==16{return Ok(true)}
  let ready=match stage{3=>{if self.numbers[0].is_some_and(|n|n>u32::MAX as u64){return Err(invalid("archive member ordinal exceeds u32"))}self.number(0,reader,cx)?},4..=13=>self.field((stage-4)as usize,true,APP_COMMAND_FIELD_MAXIMUM_BYTES,reader,cx)?,14=>self.field(0,false,APP_COMMAND_FIELD_MAXIMUM_BYTES,reader,cx)?,15=>{let bytes=10*size_of::<Option<String>>()+size_of::<Option<Vec<u8>>>()+size_of::<Option<u64>>()+size_of::<OwnedDocumentMemberPackEntry>()+size_of::<Vec<OwnedDocumentMemberPackEntry>>()+size_of::<u8>();if pay(cx,bytes,1)?{let reference=DocumentArchiveArtifactRef{artifact_id:self.texts[0].take().unwrap(),artifact_kind:self.texts[1].take().unwrap(),standard:self.texts[2].take().unwrap(),subset:self.texts[3].take().unwrap()};let parent=DocumentArchiveArtifactRef{artifact_id:self.texts[4].take().unwrap(),artifact_kind:self.texts[5].take().unwrap(),standard:self.texts[6].take().unwrap(),subset:self.texts[7].take().unwrap()};let owner=DocumentArchiveOwnerRef{parent,slot:self.texts[8].take().unwrap(),child_id:self.texts[9].take().unwrap()};self.archive.members.push(OwnedDocumentMemberPackEntry{ordinal:self.numbers[0].take().unwrap()as u32,reference,owner,envelope_pack:self.bytes[0].take().unwrap()});self.archive_stage=if self.archive.members.len()as u64==self.numbers[4].unwrap(){16}else{3}}return Ok(false)},_=>return Err(invalid("archive decoder has an impossible original frontier"))};
  if ready&&pay(cx,size_of::<u8>(),1)?{self.archive_stage+=1}Ok(false)
 }
}
impl PagedAppCommandDecodeCursor{
 /// 📥️ Decodes from original pages into a preborn output while retaining all denied or malformed input.
 pub fn step_original(&mut self,output:&mut Option<DecodedAppCommandOwner>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if output.is_some(){return Err(invalid("original command decoding requires an empty destination"))}if self.original_close.is_some(){return Err(invalid("original command decoder is closing"))}if cx.should_yield(){return Ok(false)}
  if !self.original_active{if !matches!(self.state,PagedAppCommandDecodeState::Header){return Err(invalid("original command decoder cannot adopt an ordinary decoder frontier"))}if pay(cx,size_of::<bool>(),1)?{self.original_active=true}return Ok(false)}
  let grant=cx.retained_grant();let work=cx.fuel_remaining();
  if self.original.prepared.is_some(){let bytes=size_of::<Option<DecodedAppCommandOwner>>()+size_of::<Option<AppCommand>>()+size_of::<PagedAppCommandDecodeState>();if !pay(cx,bytes,1)?{return Ok(false)}*output=Some(DecodedAppCommandOwner::new(self.original.prepared.take().unwrap()));self.state=PagedAppCommandDecodeState::Terminal;return Ok(true)}
  if matches!(self.state,PagedAppCommandDecodeState::Terminal){return Err(invalid("original command was already delivered"))}
  if self.original.tag.is_none(){if self.reader.source_page_exhausted(){debit(self.reader.release_consumed_source_step(grant,work),cx)?}else{debit(self.reader.read_byte_source_step(&mut self.original.tag,grant,work),cx)?}return Ok(false)}
  if self.original.seq.is_none(){let turn=if self.original.varint.value().is_some(){self.original.varint.transfer_source_step(&mut self.original.seq,grant,work)}else{self.original.varint.step(&mut self.reader,grant,work)};debit(turn,cx)?;return Ok(false)}
  let ready=match self.original.plan()?{Atom::Bytes(index)=>self.original.field(index,false,if self.original.tag==Some(29){142}else{APP_COMMAND_FIELD_MAXIMUM_BYTES},&mut self.reader,cx)?,Atom::Text(index)=>self.original.field(index,true,if self.original.tag==Some(37)&&index==2{2048}else{APP_COMMAND_FIELD_MAXIMUM_BYTES},&mut self.reader,cx)?,Atom::Number(index)=>{if self.original.tag.is_some_and(|tag|(38..=40).contains(&tag))&&index==0&&self.original.numbers[0].is_some_and(|n|n>u32::MAX as u64){return Err(invalid("media export app instance exceeds u32"))}self.original.number(index,&mut self.reader,cx)?},Atom::Selection=>{if let Some(value)=self.original.selection{if value>1{return Err(invalid("checkpoint selection tag must be zero or one"))}true}else{if self.reader.source_page_exhausted(){debit(self.reader.release_consumed_source_step(grant,work),cx)?}else{debit(self.reader.read_byte_source_step(&mut self.original.selection,grant,work),cx)?}false}},Atom::Ops=>self.original.ops(&mut self.reader,cx)?,Atom::Archive=>self.original.archive(&mut self.reader,cx)?,Atom::Finish=>{
   if !self.reader.source_input_consumed(){return Err(invalid("paged command carries trailing bytes after its terminal field"))}if self.reader.source_page_exhausted(){debit(self.reader.release_consumed_source_step(grant,work),cx)?;return Ok(false)}
   if self.original.tag==Some(29)&&self.original.query.is_none(){let bytes=self.original.bytes[0].as_ref().unwrap();let work=bytes.len()as u64+1;if !pay(cx,size_of::<Option<::protocol::LocalInteractionQueryCommand>>(),work)?{return Ok(false)}self.original.query=Some(::protocol::decode_local_interaction_query_command(bytes).map_err(invalid)?);return Ok(false)}
   let bytes=2*size_of::<OriginalCommandDecode>()+size_of::<Option<AppCommand>>();if !pay(cx,bytes,1)?{return Ok(false)}let mut original=std::mem::take(&mut self.original);let command=original.build();original.prepared=Some(command);self.original=original;return Ok(false)
  }};
  if ready{self.original.advance(cx)?}Ok(false)
 }
 /// 🪦️ Closes the exact retained reader, suspended parser, partial fields and ordinary-state graph on the original Source.
 pub fn close_original_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.original_retired{return Ok(true)}if cx.retirement_should_yield(){return Ok(false)}
  if self.original_close.is_none(){let bytes=size_of::<PagedCommandReader>()+size_of::<PagedAppCommandDecodeState>()+size_of::<OriginalCommandDecode>()+size_of::<Option<OriginalCursorClose>>();if !<(PagedCommandReader,PagedAppCommandDecodeState,OriginalCommandDecode)>::controlled_retirement_supported(){return Err(invalid("original command cursor lacks a complete retirement graph"))}if !pay(cx,bytes,1)?{return Ok(false)}let reader=std::mem::replace(&mut self.reader,PagedCommandReader::empty_source_home());let state=std::mem::replace(&mut self.state,PagedAppCommandDecodeState::Terminal);let original=std::mem::take(&mut self.original);self.original_close=Some(ControlledRetirement::retain((reader,state,original)));return Ok(false)}
  let owner=self.original_close.as_mut().unwrap();if owner.terminal_is_empty(){let bytes=size_of::<Option<OriginalCursorClose>>()+2*size_of::<bool>();if !pay(cx,bytes,1)?{return Ok(false)}self.original_close.take();self.original_active=false;self.original_retired=true;return Ok(true)}
  let grant=cx.retained_grant();let demand=owner.next_demand(grant.maximum_copy_bytes)?;let work=owner.next_computational_work(grant.maximum_copy_bytes)?;if cx.fuel_remaining()<work||!retained_clone_grant_admits(grant,demand){return Ok(false)}let result=owner.step(grant);cx.consume_fuel(owner.last_turn_work());match result{Ok(step)=>cx.consume_retained(step.progress())?,Err(failure)=>return Err(OriginalTurnFailure::debit_original(failure,cx))}Ok(false)
 }
}
